
'use strict';
/* ===== Extras: masnoon duas with tarjuma + alarms, qibla, nearby/favourite masjid, bookmarks & resume ===== */
const CUR=[{"c":3,"i":1,"ar":"الْحَمْدُ للَّهِ الَّذِي أَحْيَانَا بَعْدَ مَا أَمَاتَنَا، وَإِلَيْهِ النُّشُورُ","au":"/audio/1.mp3","rt":"Uthne ki dua","et":"On waking up","ut":"جاگنے کی دعا","ro":"Tamam taareef Allah ke liye jisne hamein (neend ki) maut ke baad zinda kiya, aur usi ki taraf lautna hai.","en":"All praise is for Allah who gave us life after having taken it from us, and to Him is the resurrection.","ur":"تمام تعریفیں اللہ کے لیے ہیں جس نے ہمیں (نیند کی) موت کے بعد زندہ کیا، اور اسی کی طرف لوٹ کر جانا ہے۔","n":1},{"c":3,"i":3,"ar":"الْحَمْدُ لِلَّهِ الَّذِي عَافَانِي فِي جَسَدِي، وَرَدَّ عَلَيَّ رُوحِي، وَأَذِنَ لي بِذِكْرِهِ","au":"/audio/3.mp3","rt":"Uthne ke baad shukr","et":"Thanks after waking","ut":"جاگنے کے بعد شکر","ro":"Tamam taareef Allah ke liye jisne mere jism mein aafiyat di, meri rooh mujh par lauta di aur mujhe apne zikr ki ijazat di.","en":"Praise be to Allah who gave me health in my body, returned my soul to me and permitted me to remember Him.","ur":"تمام تعریفیں اللہ کے لیے ہیں جس نے میرے جسم میں عافیت دی، میری روح مجھ پر لوٹا دی اور مجھے اپنے ذکر کی اجازت دی۔","n":1},{"c":2,"i":7,"ar":"بِاسْمِكَ اللَّهُمَّ أَمُوتُ وَأَحْيَا","au":"/audio/105.mp3","rt":"Sone ki dua","et":"Before sleeping","ut":"سونے کی دعا","ro":"Aye Allah! Tere hi naam se main marta (sota) aur jeeta (jagta) hoon.","en":"O Allah, in Your name I die and I live.","ur":"اے اللہ! تیرے ہی نام سے میں مرتا (سوتا) اور جیتا (جاگتا) ہوں۔","n":1},{"c":2,"i":4,"ar":"بِاسْمِكَ رَبِّي وَضَعْتُ جَنْبِي، وَبِكَ أَرْفَعُهُ، فَإِن أَمْسَكْتَ نَفْسِي فارْحَمْهَا، وَإِنْ أَرْسَلْتَهَا فَاحْفَظْهَا، بِمَا تَحْفَظُ بِهِ عِبَادَكَ الصَّالِحِينَ","au":"/audio/102.mp3","rt":"Sote waqt (pehlu rakhte hue)","et":"Lying down to sleep","ut":"سوتے وقت (پہلو رکھتے ہوئے)","ro":"Aye mere Rab! Tere naam se maine apna pehlu rakha aur tere hi naam se use uthaunga. Agar tu meri jaan rok le to us par rahm farma, aur agar chhod de to uski hifazat farma jaise tu apne nek bandon ki hifazat karta hai.","en":"In Your name my Lord I lay down my side and by You I raise it. If You take my soul, have mercy on it; and if You release it, protect it as You protect Your righteous servants.","ur":"اے میرے رب! تیرے نام سے میں نے اپنا پہلو رکھا اور تیرے ہی نام سے اسے اٹھاؤں گا۔ اگر تو میری جان روک لے تو اس پر رحم فرما، اور اگر چھوڑ دے تو اس کی حفاظت فرما جیسے تو اپنے نیک بندوں کی حفاظت کرتا ہے۔","n":1},{"c":2,"i":13,"ar":"اللَّهُمَّ أَسْلَمْتُ نَفْسِي إِلَيْكَ، وَفَوَّضْتُ أَمْرِي إِلَيْكَ، وَوَجَّهْتُ وَجْهِي إِلَيْكَ، وَأَلْجَأْتُ ظَهْرِي إِلَيْكَ، رَغْبَةً وَرَهْبَةً إِلَيْكَ، لاَ مَلْجَأَ وَلاَ مَنْجَا مِنْكَ إِلاَّ إِلَيْكَ، آمَنْتُ بِكِتَابِكَ الَّذِي أَنْزَلْتَ، وَبِنَبِيِّكَ الَّذِي أَرْسَلْتَ","au":"/audio/111.mp3","rt":"Sone se pehle (supurdgi ki dua)","et":"Entrusting oneself before sleep","ut":"سونے سے پہلے (سپردگی کی دعا)","ro":"Aye Allah! Maine apni jaan tere supurd ki, apna mamla tere hawale kiya, apna rukh teri taraf kiya aur apni pusht tere sahare rakhi — teri raghbat aur tere khauf ke saath. Teri pakad se bachne ka koi thikana nahi siwa teri taraf. Main tere utare hue kitab par aur tere bheje hue nabi ﷺ par imaan laya.","en":"O Allah, I submit myself to You, entrust my affairs to You, turn my face to You and lay myself down depending on You, out of hope in You and fear of You. There is no refuge or escape from You except to You. I believe in Your Book which You revealed and Your Prophet whom You sent.","ur":"اے اللہ! میں نے اپنی جان تیرے سپرد کی، اپنا معاملہ تیرے حوالے کیا، اپنا رخ تیری طرف کیا اور اپنی پشت تیرے سہارے پر رکھی — تیری رغبت اور تیرے خوف کے ساتھ۔ تیری پکڑ سے بچنے کا کوئی ٹھکانہ نہیں سوائے تیری طرف۔ میں تیری نازل کی ہوئی کتاب اور تیرے بھیجے ہوئے نبی ﷺ پر ایمان لایا۔","n":1},{"c":4,"i":1,"ar":"بِسْمِ اللَّهِ اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْخُبْثِ وَالْخَبائِث","au":"/audio/10.mp3","rt":"Bait-ul-khala mein jaate waqt","et":"Entering the toilet","ut":"بیت الخلاء میں جاتے وقت","ro":"Allah ke naam se. Aye Allah! Main napak nar aur mada jinnaat se teri panaah maangta hoon.","en":"In the name of Allah. O Allah, I seek refuge in You from male and female evil ones.","ur":"اللہ کے نام سے۔ اے اللہ! میں ناپاک نر اور مادہ جنّات سے تیری پناہ مانگتا ہوں۔","n":1},{"c":5,"i":1,"ar":"غُفْرَانَكَ","au":"/audio/11.mp3","rt":"Bait-ul-khala se nikalte waqt","et":"Leaving the toilet","ut":"بیت الخلاء سے نکلتے وقت","ro":"Aye Allah! Main teri bakhshish chahta hoon.","en":"I seek Your forgiveness.","ur":"اے اللہ! میں تیری بخشش چاہتا ہوں۔","n":1},{"c":6,"i":1,"ar":"بِسْمِ اللَّهِ","au":"/audio/12.mp3","rt":"Wudu shuru karte waqt","et":"Starting wudu","ut":"وضو شروع کرتے وقت","ro":"Allah ke naam se (wudu shuru karta hoon).","en":"In the name of Allah.","ur":"اللہ کے نام سے (وضو شروع کرتا ہوں)۔","n":1},{"c":7,"i":1,"ar":"أَشْهَدُ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ وَأَشْهَدُ أَنَّ مُحَمَّداً عَبْدُهُ وَرَسُولُهُ","au":"/audio/13.mp3","rt":"Wudu ke baad","et":"After wudu","ut":"وضو کے بعد","ro":"Main gawahi deta hoon ki Allah ke siwa koi mabood nahi, wo akela hai, uska koi shareek nahi; aur gawahi deta hoon ki Muhammad ﷺ uske bande aur rasool hain.","en":"I bear witness that none has the right to be worshipped but Allah alone, with no partner; and I bear witness that Muhammad ﷺ is His servant and Messenger.","ur":"میں گواہی دیتا ہوں کہ اللہ کے سوا کوئی معبود نہیں، وہ اکیلا ہے، اس کا کوئی شریک نہیں؛ اور گواہی دیتا ہوں کہ محمد ﷺ اس کے بندے اور رسول ہیں۔","n":1},{"c":8,"i":1,"ar":"بِسْمِ اللَّهِ، تَوَكَّلْتُ عَلَى اللَّهِ، وَلاَ حَوْلَ وَلاَ قُوَّةَ إِلاَّ بِاللَّهِ","au":"/audio/16.mp3","rt":"Ghar se nikalte waqt","et":"Leaving home","ut":"گھر سے نکلتے وقت","ro":"Allah ke naam se; maine Allah par bharosa kiya; gunah se bachne aur neki ki taqat Allah hi ki taraf se hai.","en":"In the name of Allah, I place my trust in Allah; there is no might nor power except with Allah.","ur":"اللہ کے نام سے؛ میں نے اللہ پر بھروسہ کیا؛ گناہ سے بچنے اور نیکی کرنے کی طاقت اللہ ہی کی طرف سے ہے۔","n":1},{"c":9,"i":1,"ar":"بِسْمِ اللَّهِ وَلَجْنَا، وَبِسْمِ اللَّهِ خَرَجْنَا، وَعَلَى اللَّهِ رَبِّنَا تَوَكَّلْنَا","au":"/audio/18.mp3","rt":"Ghar mein dakhil hote waqt","et":"Entering home","ut":"گھر میں داخل ہوتے وقت","ro":"Allah ke naam se hum dakhil hue, Allah ke naam se nikle, aur apne Rab Allah par bharosa kiya. (Phir ghar walon ko salam karein.)","en":"In the name of Allah we enter, in the name of Allah we leave, and upon our Lord we rely. (Then greet your family.)","ur":"اللہ کے نام سے ہم داخل ہوئے، اللہ کے نام سے نکلے، اور اپنے رب اللہ پر بھروسہ کیا۔ (پھر گھر والوں کو سلام کریں۔)","n":1},{"c":11,"i":1,"ar":"بِسْمِ اللَّهِ، وَالصَّلَاةُ وَالسَّلَامُ عَلَى رَسُولِ اللَّهِ، اللَّهُمَّ افْتَحْ لِي أَبْوَابَ رَحْمَتِكَ","au":"/audio/20.mp3","rt":"Masjid mein dakhil hote waqt","et":"Entering the masjid","ut":"مسجد میں داخل ہوتے وقت","ro":"Allah ke naam se; Allah ke Rasool ﷺ par durood o salam ho. Aye Allah! Mere liye apni rahmat ke darwaze khol de. (Pehle seedha paon rakhein.)","en":"In the name of Allah; peace and blessings upon the Messenger of Allah. O Allah, open for me the doors of Your mercy. (Enter with the right foot.)","ur":"اللہ کے نام سے؛ اللہ کے رسول ﷺ پر درود و سلام ہو۔ اے اللہ! میرے لیے اپنی رحمت کے دروازے کھول دے۔ (پہلے دایاں پاؤں رکھیں۔)","n":1},{"c":12,"i":1,"ar":"بِسْمِ اللَّهِ وَالصَّلَاةُ وَالسَّلَامُ عَلَى رَسُولِ اللَّهِ، اللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ فَضْلِكَ، اللَّهُمَّ اعْصِمْنِي مِنَ الشَّيْطَانِ الرَّجِيمِ","au":"/audio/21.mp3","rt":"Masjid se nikalte waqt","et":"Leaving the masjid","ut":"مسجد سے نکلتے وقت","ro":"Allah ke naam se; Rasoolullah ﷺ par durood o salam. Aye Allah! Main tujhse tere fazl ka sawal karta hoon; aye Allah! Mujhe shaitan mardood se bacha. (Pehle ulta paon nikalein.)","en":"In the name of Allah; peace and blessings upon the Messenger of Allah. O Allah, I ask You of Your bounty; O Allah, protect me from the accursed Shaytan. (Leave with the left foot.)","ur":"اللہ کے نام سے؛ رسول اللہ ﷺ پر درود و سلام۔ اے اللہ! میں تجھ سے تیرے فضل کا سوال کرتا ہوں؛ اے اللہ! مجھے شیطان مردود سے بچا۔ (پہلے بایاں پاؤں نکالیں۔)","n":1},{"c":14,"i":1,"ar":"الْحَمْدُ لِلَّهِ الَّذِي كَسَانِي هَذَا (الثَّوْبَ) وَرَزَقَنِيهِ مِنْ غَيْرِ حَوْلٍ مِنِّي وَلاَ قُوَّةٍ","au":"/audio/5.mp3","rt":"Kapda pehente waqt","et":"Wearing clothes","ut":"کپڑا پہنتے وقت","ro":"Tamam taareef Allah ke liye jisne mujhe ye (kapda) pehnaya aur mujhe ata kiya, meri kisi taqat aur zor ke baghair.","en":"Praise be to Allah who clothed me with this and provided it for me, with no power nor might from myself.","ur":"تمام تعریفیں اللہ کے لیے ہیں جس نے مجھے یہ (کپڑا) پہنایا اور عطا کیا، میری کسی طاقت اور زور کے بغیر۔","n":1},{"c":69,"i":1,"ar":"بِسْمِ اللَّهِ\nبِسْمِ اللَّهِ أَوَّلَهُ وَآخِرَهُ (اگر شروع میں بھول جائیں)","au":"/audio/178.mp3","rt":"Khana shuru karte waqt","et":"Before eating","ut":"کھانا شروع کرتے وقت","ro":"Allah ke naam se. (Agar shuru mein bhool jayein to kahein: Bismillahi awwalahu wa aakhirahu — Allah ke naam se, iske shuru mein bhi aur aakhir mein bhi.)","en":"In the name of Allah. (If you forget at the start, say: In the name of Allah at its beginning and its end.)","ur":"اللہ کے نام سے۔ (اگر شروع میں بھول جائیں تو کہیں: اللہ کے نام سے، اس کے شروع میں بھی اور آخر میں بھی۔)","n":1},{"c":70,"i":1,"ar":"الْحَمْدُ لِلَّهِ الَّذِي أَطْعَمَنِي هَذَا، وَرَزَقَنِيهِ، مِنْ غَيْرِ حَوْلٍ مِنِّي وَلاَ قُوَّةٍ","au":"/audio/180.mp3","rt":"Khana khane ke baad","et":"After eating","ut":"کھانے کے بعد","ro":"Tamam taareef Allah ke liye jisne mujhe ye khilaya aur rizq diya, meri kisi taqat aur zor ke baghair.","en":"Praise be to Allah who fed me this and provided it for me without any might or power from myself.","ur":"تمام تعریفیں اللہ کے لیے ہیں جس نے مجھے یہ کھلایا اور رزق دیا، میری کسی طاقت اور زور کے بغیر۔","n":1},{"c":34,"i":2,"ar":"اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ، وَالْعَجْزِ وَالْكَسَلِ، وَالْبُخْلِ وَالْجُبْنِ، وَضَلَعِ الدَّيْنِ وَغَلَبَةِ الرِّجَالِ","au":"/audio/121.mp3","rt":"Gham aur fikr ki dua","et":"Worry and grief","ut":"غم اور فکر کی دعا","ro":"Aye Allah! Main fikr aur gham se, aajizi aur susti se, bukhl aur buzdili se, qarz ke bojh aur logon ke ghalbe se teri panaah maangta hoon.","en":"O Allah, I seek refuge in You from worry and grief, weakness and laziness, miserliness and cowardice, the burden of debt and being overpowered by men.","ur":"اے اللہ! میں فکر اور غم سے، عاجزی اور سستی سے، بخل اور بزدلی سے، قرض کے بوجھ اور لوگوں کے غلبے سے تیری پناہ مانگتا ہوں۔","n":1},{"c":35,"i":1,"ar":"لاَ إِلَهَ إِلاَّ اللَّهُ الْعَظِيمُ الْحَلِيمُ، لاَ إِلَهَ إِلاَّ اللَّهُ رَبُّ الْعَرْشِ الْعَظِيمِ، لاَ إِلَهَ إِلاَّ اللَّهُ رَبُّ السَّمَوَاتِ وَرَبُّ الْأَرْضِ وَرَبُّ الْعَرْشِ الْكَرِيمِ","au":"/audio/122.mp3","rt":"Pareshani/takleef ki dua","et":"In distress","ut":"پریشانی/تکلیف کی دعا","ro":"Allah ke siwa koi mabood nahi, wo azeem o haleem (bardbaar) hai; Allah ke siwa koi mabood nahi, wo azeem arsh ka Rab hai; Allah ke siwa koi mabood nahi, wo aasmanon aur zameen ka Rab aur karam wale arsh ka Rab hai.","en":"None has the right to be worshipped but Allah, the Mighty, the Forbearing; none but Allah, Lord of the Mighty Throne; none but Allah, Lord of the heavens, Lord of the earth and Lord of the Noble Throne.","ur":"اللہ کے سوا کوئی معبود نہیں، وہ عظیم و حلیم ہے؛ اللہ کے سوا کوئی معبود نہیں، وہ عرشِ عظیم کا رب ہے؛ اللہ کے سوا کوئی معبود نہیں، وہ آسمانوں اور زمین کا رب اور عرشِ کریم کا رب ہے۔","n":1},{"c":53,"i":1,"ar":"إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ، اللَّهُمَّ أْجُرْنِي فِي مُصِيبَتِي، وَأَخْلِفْ لِي خَيْرَاً مِنْهَا","au":"/audio/154.mp3","rt":"Musibat par","et":"On a calamity","ut":"مصیبت پر","ro":"Hum Allah hi ke hain aur usi ki taraf lautne wale hain. Aye Allah! Mujhe meri musibat par ajr de aur uske badle usse behtar ata farma.","en":"Indeed we belong to Allah and to Him we shall return. O Allah, reward me in my affliction and replace it with something better.","ur":"ہم اللہ ہی کے ہیں اور اسی کی طرف لوٹنے والے ہیں۔ اے اللہ! مجھے میری مصیبت پر اجر دے اور اس کے بدلے اس سے بہتر عطا فرما۔","n":1},{"c":77,"i":1,"ar":"الْحَمْدُ لِلَّهِ\nيَرْحَمُكَ اللَّهُ\nيَهْدِيكُمُ اللَّهُ وَيُصْلِحُ بَالَكُمْ","au":"/audio/188.mp3","rt":"Chheenk aane par","et":"When sneezing","ut":"چھینک آنے پر","ro":"Chheenkne wala kahe: Alhamdulillah (tamam taareef Allah ke liye). Sunne wala kahe: Yarhamukallah (Allah tum par rahm kare). Phir chheenkne wala kahe: Yahdikumullah wa yuslihu balakum (Allah tumhein hidayat de aur tumhara haal durust rakhe).","en":"Sneezer: Alhamdulillah. Listener: Yarhamukallah (may Allah have mercy on you). Sneezer: Yahdikumullah wa yuslihu balakum (may Allah guide you and set your affairs right).","ur":"چھینکنے والا کہے: الحمدللہ۔ سننے والا کہے: یرحمک اللہ (اللہ تجھ پر رحم کرے)۔ پھر چھینکنے والا کہے: یہدیکم اللہ و یصلح بالکم (اللہ تمہیں ہدایت دے اور تمہارا حال درست رکھے)۔","n":1},{"c":79,"i":1,"ar":"بَارَكَ اللَّهُ لَكَ، وَبَارَكَ عَلَيْكَ، وَجَمَعَ بَيْنَكُمَا فِي خَيْرٍ","au":"/audio/190.mp3","rt":"Nikah par mubarakbad","et":"Congratulating the newly married","ut":"نکاح پر مبارکباد","ro":"Allah tumhein barkat de, tum par barkat naazil kare, aur tum dono ko bhalai mein jama rakhe.","en":"May Allah bless you, shower His blessings upon you and unite you both in goodness.","ur":"اللہ تمہیں برکت دے، تم پر برکت نازل کرے اور تم دونوں کو بھلائی میں جمع رکھے۔","n":1},{"c":95,"i":1,"ar":"الْحَمْدُ لِلَّهِ، الْحَمْدُ لِلَّهِ، الْحَمْدُ لِلَّهِ، اللَّهُ أَكْبَرُ، اللَّهُ أَكْبَرُ، اللَّهُ أَكْبَرُ، سُبْحَانَكَ اللَّهُمَّ إِنِّي ظَلَمْتُ نَفْسِي فَاغْفِرْ لِي؛ فَإِنَّهُ لاَ يَغْفِرُ الذُّنُوبَ إِلاَّ أَنْتَ","au":"/audio/206.mp3","rt":"Sawari par baithte waqt","et":"Boarding a ride","ut":"سواری پر بیٹھتے وقت","ro":"Allah ke naam se, tamam taareef Allah ke liye. Paak hai wo zaat jisne ise hamare tabe kar diya, warna hum ise qaboo mein nahi la sakte the, aur hum apne Rab ki taraf lautne wale hain. (Alhamdulillah 3 baar, Allahu akbar 3 baar.) Tu paak hai aye Allah! Maine apni jaan par zulm kiya, mujhe bakhsh de, kyunki tere siwa gunahon ko koi nahi bakhshta.","en":"In the name of Allah, praise be to Allah. Glory to Him who subjected this to us, and we could not have done it ourselves; and to our Lord we shall return. (Alhamdulillah ×3, Allahu akbar ×3.) Glory to You, O Allah, I have wronged myself, so forgive me; none forgives sins but You.","ur":"اللہ کے نام سے، تمام تعریفیں اللہ کے لیے ہیں۔ پاک ہے وہ ذات جس نے اسے ہمارے تابع کر دیا، ورنہ ہم اسے قابو میں نہیں لا سکتے تھے، اور ہم اپنے رب کی طرف لوٹنے والے ہیں۔ (الحمدللہ 3 بار، اللہ اکبر 3 بار۔) تو پاک ہے اے اللہ! میں نے اپنی جان پر ظلم کیا، مجھے بخش دے، کیونکہ تیرے سوا گناہوں کو کوئی نہیں بخشتا۔","n":1},{"c":82,"i":1,"ar":"أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ","au":"/audio/193.mp3","rt":"Gusse ke waqt","et":"When angry","ut":"غصے کے وقت","ro":"Main shaitan mardood se Allah ki panaah maangta hoon.","en":"I seek refuge in Allah from the accursed Shaytan.","ur":"میں شیطان مردود سے اللہ کی پناہ مانگتا ہوں۔","n":1},{"c":129,"i":3,"ar":"أَسْتَغْفِرُ اللَّهَ الْعَظِيمَ الَّذِي لاَ إِلَهَ إِلاَّ هُوَ الْحَيُّ الْقَيُّومُ وَأَتُوبُ إِلَيْهِ","au":"/audio/250.mp3","rt":"Istighfar","et":"Seeking forgiveness","ut":"استغفار","ro":"Main us azeem Allah se bakhshish maangta hoon jiske siwa koi mabood nahi, jo zinda aur qayyum hai, aur usi ki taraf tauba karta hoon.","en":"I seek forgiveness from Allah the Mighty, none has the right to be worshipped but Him, the Ever-Living, the Sustainer, and I repent to Him.","ur":"میں اس عظیم اللہ سے بخشش مانگتا ہوں جس کے سوا کوئی معبود نہیں، جو زندہ اور قائم رکھنے والا ہے، اور اسی کی طرف توبہ کرتا ہوں۔","n":1},{"c":130,"i":1,"ar":"سُبْحَانَ اللَّهِ وَبِحَمْدِهِ","au":"/audio/254.mp3","rt":"Tasbeeh (din mein 100 baar)","et":"Tasbih (100 times a day)","ut":"تسبیح (دن میں 100 بار)","ro":"Allah paak hai aur apni taareef ke saath. (Din mein 100 baar kahne se gunah maaf ho jate hain, chahe samundar ke jhaag ke barabar hon.)","en":"Glory is to Allah and praise is to Him. (Whoever says it 100 times a day, his sins are forgiven even if like the foam of the sea.)","ur":"اللہ پاک ہے اور اپنی تعریف کے ساتھ۔ (دن میں 100 بار کہنے سے گناہ معاف ہو جاتے ہیں چاہے سمندر کے جھاگ کے برابر ہوں۔)","n":100},{"c":64,"i":1,"ar":"اللَّهُمَّ صَيِّباً نَافِعاً","au":"/audio/172.mp3","rt":"Baarish ke waqt","et":"When it rains","ut":"بارش کے وقت","ro":"Aye Allah! Ise nafa dene wali baarish bana de.","en":"O Allah, make it a beneficial rain.","ur":"اے اللہ! اسے نفع دینے والی بارش بنا دے۔","n":1},{"c":68,"i":1,"ar":"ذَهَبَ الظَّمَأُ وَابْتَلَّتِ العُرُوقُ، وَثَبَتَ الْأَجْرُ إِنْ شَاءَ اللَّهُ","au":"/audio/176.mp3","rt":"Iftar ke waqt","et":"Breaking the fast","ut":"افطار کے وقت","ro":"Pyaas bujh gayi, rageen tar ho gayin, aur insha-Allah ajr sabit ho gaya.","en":"The thirst is gone, the veins are moist and the reward is confirmed, if Allah wills.","ur":"پیاس بجھ گئی، رگیں تر ہو گئیں اور ان شاء اللہ اجر ثابت ہو گیا۔","n":1},{"c":85,"i":1,"ar":"سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ، أَشْهَدُ أَنْ لاَ إِلَهَ إِلاَّ أَنْتَ، أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ","au":"/audio/196.mp3","rt":"Majlis ke baad (kaffara)","et":"End of a gathering","ut":"مجلس کے بعد (کفارہ)","ro":"Aye Allah! Tu paak hai apni taareef ke saath; main gawahi deta hoon ki tere siwa koi mabood nahi; main tujhse bakhshish maangta hoon aur teri taraf tauba karta hoon.","en":"Glory and praise be to You, O Allah. I bear witness that none has the right to be worshipped but You; I seek Your forgiveness and repent to You.","ur":"اے اللہ! تو پاک ہے اپنی تعریف کے ساتھ؛ میں گواہی دیتا ہوں کہ تیرے سوا کوئی معبود نہیں؛ میں تجھ سے بخشش مانگتا ہوں اور تیری طرف توبہ کرتا ہوں۔","n":1},{"c":87,"i":1,"ar":"جَزَاكَ اللَّهُ خَيْراً","au":"/audio/198.mp3","rt":"Ehsaan karne walay ke liye","et":"For one who did you a favour","ut":"احسان کرنے والے کے لیے","ro":"Allah tumhein behtareen badla de.","en":"May Allah reward you with goodness.","ur":"اللہ تمہیں بہترین بدلہ دے۔","n":1},{"c":93,"i":1,"ar":"وَفِيكَ بَارَكَ اللَّهُ","au":"/audio/204.mp3","rt":"\"Barakallahu fik\" ka jawab","et":"Reply to \"Barakallahu fik\"","ut":"\"بارک اللہ فیک\" کا جواب","ro":"Aur tumhein bhi Allah barkat de.","en":"And may Allah bless you too.","ur":"اور تمہیں بھی اللہ برکت دے۔","n":1},{"c":100,"i":1,"ar":"أَسْتَوْدِعُكُمُ اللَّهَ الَّذِي لاَ تَضِيعُ وَدَائِعُهُ","au":"/audio/211.mp3","rt":"Safar par jaate waqt (muqeem ke liye)","et":"Traveller to those staying","ut":"سفر پر جاتے وقت (مقیم کے لیے)","ro":"Main tumhein us Allah ke supurd karta hoon jiske paas rakhi hui amaanatein zaya nahi hotin.","en":"I entrust you to Allah, whose trusts are never lost.","ur":"میں تمہیں اس اللہ کے سپرد کرتا ہوں جس کے پاس رکھی ہوئی امانتیں ضائع نہیں ہوتیں۔","n":1},{"c":104,"i":1,"ar":"أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ مِنْ شَرِّ مَا خَلَقَ","au":"/audio/216.mp3","rt":"Kisi jagah ruk kar","et":"Stopping at a place","ut":"کسی جگہ ٹھہر کر","ro":"Main Allah ke mukammal kalimaat ki panaah maangta hoon har us cheez ke shar se jo usne paida ki.","en":"I seek refuge in the perfect words of Allah from the evil of what He has created.","ur":"میں اللہ کے مکمل کلمات کی پناہ مانگتا ہوں ہر اس چیز کے شر سے جو اس نے پیدا کی۔","n":1},{"c":124,"i":1,"ar":"بِسْمِ اللَّهِ (٣ مرتبہ)\nأَعُوذُ بِاللَّهِ وَقُدْرَتِهِ مِنْ شَرِّ مَا أَجِدُ وَأُحَاذِرُ (٧ مرتبہ)","au":"/audio/243.mp3","rt":"Jism mein dard par","et":"Pain in the body","ut":"جسم میں درد پر","ro":"Jahan dard ho wahan haath rakh kar 3 baar Bismillah kahein, phir 7 baar: Main Allah ki aur uski qudrat ki panaah maangta hoon us takleef ke shar se jo mujhe hai aur jisse mujhe andesha hai.","en":"Place your hand on the painful spot, say Bismillah 3 times, then 7 times: I seek refuge in Allah and His power from the evil of what I feel and fear.","ur":"جہاں درد ہو وہاں ہاتھ رکھ کر 3 بار بسم اللہ کہیں، پھر 7 بار: میں اللہ کی اور اس کی قدرت کی پناہ مانگتا ہوں اس تکلیف کے شر سے جو مجھے ہے اور جس سے مجھے اندیشہ ہے۔","n":1},{"c":26,"i":1,"ar":"اللَّهُــمَّ إِنِّي أَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ، وَمِنْ عَذَابِ جَهَنَّمَ، وَمِنْ فِتْنَةِ الْمَحْيَا وَالْمَمَاتِ، وَمِنْ شَرِّ فِتْنَةِ الْمَسِيحِ الدَّجَّالِ","au":"/audio/55.mp3","rt":"Tashahhud ke baad (panaah)","et":"After the final tashahhud","ut":"آخری تشہد کے بعد (پناہ)","ro":"Aye Allah! Main qabr ke azaab se, jahannam ke azaab se, zindagi aur maut ke fitne se aur masih dajjal ke fitne ke shar se teri panaah maangta hoon.","en":"O Allah, I seek refuge in You from the torment of the grave, the torment of Hell, the trials of life and death and the evil of the trial of the False Messiah.","ur":"اے اللہ! میں قبر کے عذاب سے، جہنم کے عذاب سے، زندگی اور موت کے فتنے سے اور مسیح دجال کے فتنے کے شر سے تیری پناہ مانگتا ہوں۔","n":1}];
const trOf=c=>S.lang==='ur'?c.ur:isEnL()?c.en:c.ro;
const ttlOf=c=>S.lang==='ur'?c.ut:isEnL()?c.et:c.rt;
const curKey=c=>c.c+':'+c.i;
let DMEM=store.get('dua_mem',{});
const dayNum=()=>Math.floor((Date.now()-new Date().getTimezoneOffset()*60000)/864e5);
function dailyDua(){const pend=CUR.filter(c=>!DMEM[curKey(c)]);const L=pend.length?pend:CUR;return L[dayNum()%L.length]}
/* ---------- alarm events (wake / sleep / meals / daily yaad) ---------- */
function duaEvents(base){const D=S.dua,out=[],at=h=>atTime(h,base);
  const add=(k,d,title,body,voice)=>{if(d)out.push({k,at:d,title,body,voice:voice&&voice!=='alert'?voice:'alert_dua',tab:'deen',sub:'duas'})};
  if(D.wakeOn)add('dwk',at(D.wake),T('Uthne ka waqt ho chuka hai ☀️','Time to wake up ☀️','جاگنے کا وقت ہو چکا ہے ☀️','जागने का वक़्त हो चुका है ☀️'),T('Dua padh lijiye: Alhamdulillahil-ladhi ahyana ba\'da ma amatana wa ilayhin-nushur — Tamam taareef Allah ke liye jisne hamein maut (neend) ke baad zinda kiya.','Please recite the dua: Praise be to Allah who gave us life after causing us to die.','دعا پڑھ لیجیے: الحمد للہ الذی احیانا بعد ما اماتنا والیہ النشور','दुआ पढ़ लीजिये: अल-हम्दु लिल्लाहिल-लज़ी अह्याना बादा मा अमातना व इलैहिन-नुशूर'),'dua_wake');//T('Alhamdulillahil-ladhi ahyana ba\'da ma amatana wa ilayhin-nushur — Tamam taareef Allah ke liye jisne hamein maut (neend) ke baad zinda kiya.','Praise be to Allah who gave us life after causing us to die.','الحمد للہ الذی احیانا بعد ما اماتنا والیہ النشور — تمام تعریفیں اللہ کے لیے جس نے ہمیں (نیند کی) موت کے بعد زندہ کیا۔'),'dua_wake');
  if(D.sleepOn)add('dsl',at(D.sleep),T('Sone ka waqt ho chuka hai 🌙','Time to sleep 🌙','سونے کا وقت ہو چکا ہے 🌙','सोने का वक़्त हो चुका है 🌙'),T('Dua padh lijiye: Bismika Allahumma amutu wa ahya — Aye Allah! Tere hi naam se marta (sota) aur jeeta (jagta) hoon.','Please recite the dua: O Allah, in Your name I die and I live.','دعا پڑھ لیجیے: باسمک اللہم اموت و احیا','दुआ पढ़ लीजिये: बिस्मिका अल्लाहुम्मा अमूतु व अह्या'),'dua_sleep');//T('Bismika Allahumma amutu wa ahya — Aye Allah! Tere hi naam se marta (sota) aur jeeta (jagta) hoon.','O Allah, in Your name I die and I live.','باسمک اللہم اموت و احیا — اے اللہ! تیرے ہی نام سے میں مرتا (سوتا) اور جیتا (جاگتا) ہوں۔'),'dua_sleep');
  if(D.mealOn)[['b','Nashta','Breakfast'],['l','Dopahar ka khana','Lunch'],['d','Raat ka khana','Dinner']].forEach(([k,r,e])=>{const t=at(D[k]);if(!t)return;
    add('dm1'+k,t,T(`${r} — khane ki dua 🍽`,`${e} — dua before eating 🍽`),T('Bismillah — Allah ke naam se shuru. Bhool jayein to: Bismillahi awwalahu wa aakhirahu.','Bismillah — in the name of Allah. If you forget: Bismillahi awwalahu wa aakhirahu.'),'dua_eat1');
    const a=new Date(t);a.setMinutes(a.getMinutes()+(+D.after||20));
    add('dm2'+k,a,T('Khane ke baad ki dua','Dua after eating'),T('Alhamdulillahil-ladhi at\'amani hadha wa razaqanihi min ghayri hawlin minni wa la quwwa — Tamam taareef Allah ke liye jisne mujhe ye khilaya aur rizq diya.','Praise be to Allah who fed me this and provided it for me.'),'dua_eat2')});
  if(D.dailyOn){const c=dailyDua();add('ddl',at(D.daily),T('Aaj ki dua yaad karein 📿','Dua of the day 📿'),ttlOf(c)+': '+trOf(c).slice(0,110),'alert')}
  return out}
/* ---------- dua pages ---------- */
function curCard(c,i){const k=curKey(c),m=DMEM[k];
  return`<div class="card hd"><div class="row sp"><b>${esc(ttlOf(c))}</b><span class="chip ${m?'ok':'gold'}">${m?'✓ '+T('Yaad','Learnt'):'#'+(i+1)}</span></div>
   <div class="q-ar one hda" style="margin-top:10px;font-family:AmiriQ,Naskh,serif;line-height:2.3;white-space:pre-line">${esc(c.ar)}</div>
   <div class="${S.lang==='ur'?'urdu':'trx'} hdt" style="margin-top:8px;${S.lang==='ur'?'':'direction:ltr;text-align:start'}"><span class="eyebrow" style="font-size:10px">${T('TARJUMA','TRANSLATION','ترجمہ','अनुवाद')}</span><br>${esc(trOf(c))}</div>
   <div class="row wrap mt"><button class="btn s gold dmsay" data-a="dmsay">▶ ${T('Suno','Listen')}</button><button class="btn s ghost dmsay" data-a="dmsay" data-t="tr">🗣 ${T('Tarjuma','Translation')}</button><button class="btn s ghost dmplay" data-a="dmplay" data-p="${esc(c.au)}" title="Qari">🎧</button><button class="btn s ghost ${m?'rdon':''}" data-a="dmmem" data-k="${k}">${m?T('✓ Yaad hai','✓ Learnt'):T('Yaad ho gayi','Learnt')}</button><button class="btn s ghost" data-a="dmcopy2" data-k="${k}">⧉</button></div></div>`}
function duaAlarmCard(){const D=S.dua;
  const tr=(on,tm,l)=>`<div class="fs"><span>${l}</span><span class="row" style="gap:8px"><input type="time" data-a="set" data-p="dua.${tm}" data-t="time" value="${D[tm]}" style="width:auto;margin:0"><input type="checkbox" class="sw" data-a="set" data-p="dua.${on}" data-t="check" ${D[on]?'checked':''}></span></div>`;
  const pl=(v,l)=>`<button class="btn s ghost" data-a="dmtest" data-v="${v}">▶ ${l}</button>`;
  return`<div class="card hero"><h2 style="margin:0">⏰ ${T('Duaon ke alarm','Dua alarms','دعاؤں کے الارم','दुआओं के अलार्म')}</h2>
   <p class="muted sm">${T('Waqt par alarm bajta hai, phir dua zor se sunai jaati hai — screen band ho tab bhi (alarm ki awaaz par). Notification mein tarjuma likha aata hai, awaaz sirf dua ki hoti hai.','At the set time an alarm rings and the dua is recited aloud — even with the screen off. The notification shows the translation; the audio is the dua only.')}</p>
   ${tr('wakeOn','wake','☀️ '+T('Uthne ka alarm + dua','Wake-up alarm + dua'))}${tr('sleepOn','sleep','🌙 '+T('Sone ki dua','Sleep dua'))}
   <div class="fs"><span>🍽 ${T('Khane ki dua (pehle aur baad)','Meal duas (before & after)')}</span><input type="checkbox" class="sw" data-a="set" data-p="dua.mealOn" data-t="check" ${D.mealOn?'checked':''}></div>
   <div class="mrow"><b>${T('Nashta','Breakfast')}</b><input type="time" data-a="set" data-p="dua.b" data-t="time" value="${D.b}"></div><div class="mrow"><b>${T('Dopahar','Lunch')}</b><input type="time" data-a="set" data-p="dua.l" data-t="time" value="${D.l}"></div><div class="mrow"><b>${T('Raat','Dinner')}</b><input type="time" data-a="set" data-p="dua.d" data-t="time" value="${D.d}"></div>
   <div class="fs"><span>${T('Khane ke kitni der baad "baad ki dua" yaad dilaun (min)','Remind "after-meal dua" after (min)')}</span><input type="number" inputmode="numeric" data-a="set" data-p="dua.after" data-t="number" value="${D.after}" style="width:80px;margin:0"></div>
   ${tr('dailyOn','daily','📿 '+T('Roz ek dua yaad karwana','Daily dua to memorise'))}
   <div class="row wrap mt">${pl('dua_wake',T('Uthne','Wake'))}${pl('dua_sleep',T('Sone','Sleep'))}${pl('dua_eat1',T('Khane se pehle','Before meal'))}${pl('dua_eat2',T('Khane ke baad','After meal'))}</div>
   <p class="muted sm">${T('Alarm ki awaaz phone ke "Alarm" volume par chalti hai — volume upar rakhein. Settings mein "Exact alarm" aur battery optimisation allow karna zaroori hai.','The alarm plays on the phone\'s "Alarm" volume — keep it up. Allow Exact alarms and disable battery optimisation in Settings.')}</p></div>`}
function dailyCard(){const c=dailyDua(),n=Object.keys(DMEM).filter(k=>DMEM[k]).length;
  return`<div class="card hero"><div class="row sp"><div class="eyebrow">${T('AAJ KI DUA — YAAD KAREIN','DUA OF THE DAY — MEMORISE')}</div><span class="chip gold">${n}/${CUR.length} ${T('yaad','learnt')}</span></div>
   <b style="font-size:16px">${esc(ttlOf(c))}</b><div class="q-ar one hda" style="margin-top:8px;font-family:AmiriQ,Naskh,serif;line-height:2.2;white-space:pre-line">${esc(c.ar)}</div>
   <div class="${S.lang==='ur'?'urdu':'trx'}" style="margin-top:6px;${S.lang==='ur'?'':'direction:ltr;text-align:start'}">${esc(trOf(c))}</div>
   <div class="row wrap mt"><button class="btn s gold dmplay" data-a="dmplay" data-p="${esc(c.au)}">▶ ${T('Suno','Listen')}</button><button class="btn s ghost" data-a="dmmem" data-k="${curKey(c)}">${DMEM[curKey(c)]?T('✓ Yaad hai','✓ Learnt'):T('✅ Yaad ho gayi','✅ Learnt')}</button></div></div>`}
async function renderDuas(el){const t=DM.t||'cur';
  const bar=`<div class="fch">${[['cur',T('📿 Roz ki duain','📿 Daily duas')],['alarm',T('⏰ Alarm','⏰ Alarms')],['book',T('📘 Poori kitab','📘 Full book')]].map(x=>`<button data-a="dmt" data-v="${x[0]}" class="${t===x[0]?'on':''}">${x[1]}</button>`).join('')}</div>`;
  if(t==='book'){el.innerHTML=bar+'<div id="dbk"></div>';return renderDuaBook($('#dbk'))}
  if(t==='alarm'){el.innerHTML=bar+(typeof almCard==='function'?almCard():'')+duaAlarmCard();return}
  const n=Object.keys(DMEM).filter(k=>DMEM[k]).length;
  el.innerHTML=bar+dailyCard()+`<div class="card"><div class="row sp"><h2 style="margin:0">${T('Masnoon duain — tarjuma ke saath','Masnoon duas — with translation','مسنون دعائیں — ترجمہ کے ساتھ','मसनून दुआएँ — अनुवाद के साथ')}</h2><span class="chip ok">${n}/${CUR.length}</span></div><div class="muted sm">${T('Awaaz Hisnul Muslim ki recitation hai (internet chahiye). Tarjuma sirf padhne ke liye likha hai.','Audio is the Hisnul Muslim recitation (needs internet). Translation is shown as text.')}</div></div>`+fsRow()+`<input id="curq" class="srch" placeholder="🔎 ${T('Dua dhoondhein: khana, sone, safar, uthna…','Search duas: food, sleep, travel, waking…','دعا تلاش کریں: کھانا، سونا، سفر، اٹھنا…','दुआ खोजें: खाना, सोना, सफ़र, उठना…')}" value="${esc(DM.cq||'')}" style="margin:8px 0">`+`<div id="curl">${curListHTML()}</div>`;
  const cq=$('#curq');if(cq)cq.oninput=debounce(()=>{DM.cq=cq.value;const l=$('#curl');if(l)l.innerHTML=curListHTML()},200)}
function curListHTML(){const q0=nrm(DM.cq||'').toLowerCase(),q=/^[a-z ]+$/.test(q0)&&q0.length>=4?q0.slice(0,-1):q0;const L=CUR.map((c,i)=>[c,i]).filter(([c])=>!q||nrm([c.rt,c.et,c.ut,c.ro,c.en,c.ur,c.ar].join(' ')).toLowerCase().includes(q));return L.map(([c,i])=>curCard(c,i)).join('')||`<p class="muted c">${T('Kuch nahi mila.','Nothing found.')}</p>`}
/* ---------- QIBLA ---------- */
const KAABA=[21.4225,39.8262];
const QB={h:null,on:false,sm:null};
function geoPos(){return S.lat!=null?[S.lat,S.lng]:null}
function qiblaBearing(la,lo){const r=Math.PI/180,f1=la*r,f2=KAABA[0]*r,dl=(KAABA[1]-lo)*r,y=Math.sin(dl)*Math.cos(f2),x=Math.cos(f1)*Math.sin(f2)-Math.sin(f1)*Math.cos(f2)*Math.cos(dl);return(Math.atan2(y,x)/r+360)%360}
function distKm(a,b,c,d){const r=Math.PI/180,x=(c-a)*r,y=(d-b)*r,h=Math.sin(x/2)**2+Math.cos(a*r)*Math.cos(c*r)*Math.sin(y/2)**2;return 12742*Math.asin(Math.sqrt(h))}
function qiblaCard(){const p=geoPos(),b=p?qiblaBearing(p[0],p[1]):null;
  const body=p?`<div class="compass" id="qcomp"><svg viewBox="0 0 240 240"><g id="qdial"><circle cx="120" cy="120" r="108" class="cr"/><circle cx="120" cy="120" r="92" class="cr2"/>${[0,90,180,270].map((a,i)=>`<text x="120" y="${34}" transform="rotate(${a} 120 120)" class="cn">${['N','E','S','W'][i]}</text>`).join('')}${Array.from({length:36},(_,i)=>`<line x1="120" y1="14" x2="120" y2="${i%9===0?26:20}" transform="rotate(${i*10} 120 120)" class="ct"/>`).join('')}<g transform="rotate(${b} 120 120)"><path d="M120 46 l9 34 h-18z" class="qk"/><text x="120" y="102" class="kb">🕋</text></g></g><path d="M120 6 l7 16 h-14z" class="ptr0"/></svg></div>
    <div class="c" id="qinfo"><b style="font-size:18px">${Math.round(b)}°</b> <span class="muted">${T('Qibla (North se)','Qibla (from North)')}</span> • <span class="muted">${Math.round(distKm(p[0],p[1],KAABA[0],KAABA[1])).toLocaleString()} km</span></div><div class="c muted sm" id="qstat">${QB.on?(QB.h==null?T('Compass sensor ka intezar…','Waiting for sensor…'):''):T('Compass shuru karein, phir phone ko seedha (zameen ke barabar) pakdein.','Start the compass, then hold the phone flat.')}</div>
    <div class="row wrap mt" style="justify-content:center"><button class="btn s ${QB.on?'ghost':'gold'}" data-a="qbstart">${QB.on?T('⏹ Compass band','⏹ Stop'):T('🧭 Compass shuru','🧭 Start compass')}</button><button class="btn s ghost" data-a="gps">📍 GPS</button></div>`
   :`<p class="muted">${T('Qibla ke liye location chahiye.','Location is needed for the Qibla.')}</p><div class="row wrap"><button class="btn s gold" data-a="gps">📍 ${T('GPS se location lein','Use GPS')}</button></div>`;
  return`<div class="card"><h2>🧭 ${T('Qibla compass','Qibla compass','قبلہ کمپاس','क़िबला कंपास')}</h2>${body}<p class="muted sm">${T('Compass phone ke magnetic sensor se chalta hai — dhaatu/magnet se door rakhein, 8 ki shakal mein ghuma kar calibrate karein. Tareeqa sirf andaza hai, mazeed tasdeeq ke liye masjid ka mehrab dekhein.','Uses the phone\'s magnetic sensor — keep away from metal; calibrate by moving in a figure-8. It is an aid; confirm with the masjid\'s mihrab.')}</p></div>`}
function qiblaDraw(){const d=$('#qdial');if(!d||QB.h==null)return;d.style.transform=`rotate(${-QB.h}deg)`;d.style.transformOrigin='120px 120px';
  const p=geoPos();if(!p)return;const b=qiblaBearing(p[0],p[1]);let diff=Math.abs(((b-QB.h+540)%360)-180);
  const st=$('#qstat'),cp=$('#qcomp');const ok=diff<=4;
  if(ok){QB.hold=(QB.hold||0)+1;if(QB.hold>=4&&!QB.armed){QB.armed=true;qiblaAlert()}}else{QB.hold=0;if(diff>9)QB.armed=false}if(cp)cp.classList.toggle('ok',ok);if(st)st.innerHTML=ok?`<b style="color:var(--ok)">✅ ${T('Aap Qibla ki taraf hain','Facing the Qibla')}</b>`:`${T('Qibla se farq','Off by')} ${Math.round(diff)}°`}
function qiblaAlert(){try{if(navigator.vibrate)navigator.vibrate([220,90,220])}catch(e){}
  try{const C=window.AudioContext||window.webkitAudioContext;if(!C)return;QB.ac=QB.ac||new C();const c=QB.ac;if(c.state==='suspended')c.resume();const t=c.currentTime;
    [[880,0],[1175,.18]].forEach(([f,d])=>{const o=c.createOscillator(),g=c.createGain();o.type='sine';o.frequency.value=f;g.gain.setValueAtTime(0,t+d);g.gain.linearRampToValueAtTime(.4,t+d+.02);g.gain.exponentialRampToValueAtTime(.001,t+d+.16);o.connect(g);g.connect(c.destination);o.start(t+d);o.stop(t+d+.18)})}catch(e){}}
function onOrient(e){let h=null;if(e.webkitCompassHeading!=null)h=e.webkitCompassHeading;else if(e.alpha!=null&&(e.absolute||e.type==='deviceorientationabsolute'))h=360-e.alpha;if(h==null||isNaN(h))return;
  if(QB.sm==null)QB.sm=h;else{let d=((h-QB.sm+540)%360)-180;QB.sm=(QB.sm+d*0.25+360)%360}QB.h=QB.sm;qiblaDraw()}
async function qiblaToggle(){if(QB.on){QB.on=false;window.removeEventListener('deviceorientationabsolute',onOrient,true);window.removeEventListener('deviceorientation',onOrient,true);return rerender()}
  try{if(typeof DeviceOrientationEvent!=='undefined'&&typeof DeviceOrientationEvent.requestPermission==='function'){const r=await DeviceOrientationEvent.requestPermission();if(r!=='granted'){toast(T('Sensor ki ijazat nahi mili','Sensor permission denied'));return}}}catch(e){}
  QB.on=true;QB.sm=null;QB.h=null;QB.hold=0;QB.armed=false;try{(window.AudioContext||window.webkitAudioContext)&&(QB.ac=QB.ac||new (window.AudioContext||window.webkitAudioContext)())}catch(e){}window.addEventListener('deviceorientationabsolute',onOrient,true);window.addEventListener('deviceorientation',onOrient,true);rerender();
  setTimeout(()=>{if(QB.on&&QB.h==null){const s=$('#qstat');if(s)s.textContent=T('Is device mein compass sensor nahi mila. Upar diya hua degree dekh kar kisi compass/Google Maps se milaein.','No compass sensor found on this device. Use the bearing above with another compass.')}},3000)}
/* ---------- NEARBY + FAVOURITE MASJIDS ---------- */
const MQ={list:store.get('mq_list',null),busy:false,err:''};
const dFmt=m=>m<1000?Math.round(m)+' m':(m/1000).toFixed(1)+' km';
async function mqCoords(){if(S.lat!=null)return[S.lat,S.lng];return new Promise((res,rej)=>{if(!navigator.geolocation)return rej(new Error('no gps'));navigator.geolocation.getCurrentPosition(p=>{S.lat=p.coords.latitude;S.lng=p.coords.longitude;saveS();res([S.lat,S.lng])},()=>rej(new Error('denied')),{timeout:15000,enableHighAccuracy:false})})}
async function mqFind(){if(MQ.busy)return;MQ.busy=true;MQ.err='';rerender();
  try{const[la,lo]=await mqCoords();let els=[];
    for(const R of [2500,6000]){const q=`[out:json][timeout:25];(node["amenity"="place_of_worship"]["religion"="muslim"](around:${R},${la},${lo});way["amenity"="place_of_worship"]["religion"="muslim"](around:${R},${la},${lo}););out center 60;`;let ok=false;
      for(const ep of ['https://overpass-api.de/api/interpreter','https://overpass.kumi.systems/api/interpreter']){try{const c=new AbortController(),to=setTimeout(()=>c.abort(),20000);const r=await fetch(ep,{method:'POST',body:'data='+encodeURIComponent(q),headers:{'Content-Type':'application/x-www-form-urlencoded'},signal:c.signal});clearTimeout(to);if(!r.ok)continue;els=(await r.json()).elements||[];ok=true;break}catch(e){}}
      if(!ok)throw new Error('net');if(els.length>=5)break}
    const L=els.map(e=>{const t=e.tags||{},y=e.lat??(e.center&&e.center.lat),x=e.lon??(e.center&&e.center.lon);if(y==null)return null;
      return{id:e.type[0]+e.id,n:t['name']||t['name:ur']||t['name:en']||t['name:hi']||T('Masjid (naam darj nahi)','Masjid (unnamed)'),lat:y,lng:x,d:distKm(la,lo,y,x)*1000}}).filter(Boolean).sort((a,b)=>a.d-b.d).slice(0,30);
    MQ.list={t:Date.now(),la,lo,L};store.set('mq_list',MQ.list)}
  catch(e){MQ.err=e.message==='denied'||e.message==='no gps'?T('Location ki ijazat nahi mili — GPS on karke allow karein.','Location permission needed — enable GPS and allow.'):T('Masjid ki list nahi mil saki — internet check karein.','Could not fetch the list — check internet.')}
  MQ.busy=false;rerender()}
const isFav=id=>S.favs.some(f=>f.id===id);
function favApply(i){const f=S.favs[i];if(!f)return;S.favAct=i;S.masjid.jz=f.jz||'';S.masjid.ju=f.ju||'';S.masjid.name=f.name;S.masjid.az=Object.assign({},f.az||{});S.masjid.jm=Object.assign({},f.jm||{});saveS();if(typeof schedTick==='function')schedTick();if(typeof nativeSync==='function')nativeSync()}
function favMigrate(){if(!S.favs.length&&S.masjid&&S.masjid.name){S.favs.push({id:'own',name:S.masjid.name,jz:S.masjid.jz||'',ju:S.masjid.ju||'',lat:null,lng:null,az:Object.assign({},S.masjid.az),jm:Object.assign({},S.masjid.jm)});S.favAct=0;saveS()}}
function nearCard(){const m=MQ.list;const maps=(m?`https://www.google.com/maps/search/masjid/@${m.la},${m.lo},15z`:'https://www.google.com/maps/search/masjid+near+me');
  const rows=m&&m.L.length?m.L.map(x=>`<div class="sr" style="align-items:center"><div class="no"><b>🕌</b></div><div class="nm"><b>${esc(x.n)}</b><div class="muted sm">${dFmt(x.d)}</div></div><button class="btn s ${isFav(x.id)?'rdon':'ghost'}" data-a="favtog" data-id="${x.id}">${isFav(x.id)?'⭐':'☆'}</button><a class="btn s ghost" target="_blank" rel="noopener" href="https://www.google.com/maps/dir/?api=1&destination=${x.lat},${x.lng}&travelmode=walking">🧭</a></div>`).join(''):'';
  return`<div class="card"><div class="row sp"><h2 style="margin:0">🕌 ${T('Qareeb ki masjidein','Nearby masjids','قریب کی مساجد','पास की मस्जिदें')}</h2><button class="btn s gold" data-a="mqfind" ${MQ.busy?'disabled':''}>${MQ.busy?'…':T('📍 Dhundhein','📍 Find')}</button></div>
   ${MQ.err?`<div class="warnbox">${esc(MQ.err)}</div>`:''}${m?`<div class="muted sm">${m.L.length} ${T('masjid mili','found')} • ${new Date(m.t).toLocaleTimeString(LOC(),{hour:'2-digit',minute:'2-digit'})} • ${T('Data: OpenStreetMap','Data: OpenStreetMap')}</div>`:`<p class="muted sm">${T('Aap ki location se 2–6 km ke andar ki masjidein (nazdeek se door).','Masjids within 2–6 km of your location (nearest first).')}</p>`}
   ${rows?`<div class="card flat mt">${rows}</div>`:''}<div class="row wrap mt"><a class="btn s ghost" target="_blank" rel="noopener" href="${maps}">🗺 ${T('Google Maps mein dekhein','Open in Google Maps')}</a></div>
   <p class="muted sm">${T('⭐ dabane se wo masjid "Favourite" ban jati hai aur uski jamaat ka waqt Home par sab se upar dikhta hai.','Tap ⭐ to make it a Favourite — its jamaat times appear at the top of Home.')}</p></div>`}
function favListCard(){favMigrate();if(!S.favs.length)return'';
  return`<div class="card"><h2>⭐ ${T('Meri favourite masjidein','My favourite masjids')}</h2>${S.favs.map((f,i)=>`<div class="sr" style="align-items:center"><div class="no"><b>${i===S.favAct?'✅':'🕌'}</b></div><div class="nm"><b>${esc(f.name)}</b><div class="muted sm">${i===S.favAct?T('Home par dikh rahi hai','Shown on Home'):T('Tap karke chunein','Tap to use')}</div></div><button class="btn s ghost" data-a="favuse" data-i="${i}">${T('Chunein','Use')}</button><button class="btn s ghost" data-a="favedit" data-i="${i}">⏱</button><button class="btn s ghost" data-a="favdel" data-i="${i}">✕</button></div>`).join('')}</div>`}
function favForm(i){const f=S.favs[i];if(!f)return;const row=p=>`<div class="mrow"><b>${pname(p)}</b><input type="time" id="fa_${p}" value="${(f.az||{})[p]||''}" aria-label="Azan"><input type="time" id="fj_${p}" value="${(f.jm||{})[p]||''}" aria-label="Jamaat"></div>`;
  dlg(`<h2 class="h2">🕌 ${esc(f.name)}</h2><div class="mrow mh"><span></span><span>${T('Azan','Azan')}</span><span>${T('Jamaat','Jamaat')}</span></div>${PRAY.map(row).join('')}<div class="mrow"><b>${T('Jumma','Jumma','جمعہ','जुमा')}</b><input type="time" id="fa_ju" value="${f.jz||''}" aria-label="Jumma azan"><input type="time" id="fj_ju" value="${f.ju||''}" aria-label="Jumma jamaat"></div>
   <p class="muted sm">${T('Is masjid ki azan/jamaat ka waqt likhein. Khali chhorein to hisaab wala waqt use hoga.','Enter this masjid\'s azan/jamaat times. Blank = calculated.')}</p>
   <div class="row mt"><button class="btn ghost grow" id="fx">${T('Cancel','Cancel')}</button><button class="btn grow" id="fo">${T('Save karein','Save')}</button></div>`);
  $('#fx').onclick=closeDlg;$('#fo').onclick=()=>{f.az={};f.jm={};PRAY.forEach(p=>{const a=$('#fa_'+p).value,j=$('#fj_'+p).value;if(hm(a))f.az[p]=a;if(hm(j))f.jm[p]=j});{const a=$('#fa_ju').value,j=$('#fj_ju').value;f.jz=hm(a)?a:'';f.ju=hm(j)?j:''}saveS();if(S.favAct===i)favApply(i);closeDlg();toast(T('Save ho gaya ✅','Saved ✅'));rerender()}}
function favHomeCard(){favMigrate();const f=S.favs[S.favAct]||S.favs[0];
  if(!f)return`<div class="card tap" data-a="tab" data-v="deen" data-s="namaz"><div class="row"><span class="mosq">🕌</span><div class="grow"><b>${T('Apni favourite masjid chunein','Choose your favourite masjid')}</b><div class="muted sm">${T('Qareeb ki masjid dhundh kar ⭐ lagayein — jamaat ka waqt yahan upar dikhega.','Find a nearby masjid and tap ⭐ — its jamaat times will show here.')}</div></div><span>›</span></div></div>`;
  const now=new Date();let nxt=null;const isFri=now.getDay()===5;const jt=PRAY.map(p=>{let d=(f===S.favs[S.favAct])?jamTime(p):(f.jm&&hm(f.jm[p])?atTime(f.jm[p]):null);if(isFri&&p==='Dhuhr'){const j=juTimes();if(j.jm)d=j.jm}return{p,d,lbl:(isFri&&p==='Dhuhr')?T('Jumma','Jumma','جمعہ','जुमा'):pname(p)}});
  for(const x of jt){if(x.d&&x.d>now){nxt=x;break}}
  return`<div class="card favm"><div class="row sp"><div class="row" style="gap:10px;min-width:0"><span class="mosq">🕌</span><div style="min-width:0"><div class="eyebrow">${T('MERI FAVOURITE MASJID','MY FAVOURITE MASJID')}</div><b style="font-size:17px">${esc(f.name)}</b></div></div><button class="btn s ghost" data-a="favedit" data-i="${S.favAct}">⏱</button></div>
   <div class="fjr mt">${jt.map(x=>`<div class="fj${nxt&&nxt.p===x.p?' nx':''}"><span>${x.lbl}</span><b>${x.d?t12(hhmmOf(x.d)):'—'}</b></div>`).join('')}</div>${(()=>{const j=juTimes();return j.jm?`<div class="muted sm mt">🕌 ${T('Jumma','Jumma','جمعہ','जुमा')}: ${T('Azan','Azan')} ${j.az?t12(hhmmOf(j.az)):'—'} • ${T('Jamaat','Jamaat')} <b>${t12(hhmmOf(j.jm))}</b></div>`:''})()}
   ${nxt?`<div class="muted sm mt">${T('Agli jamaat','Next jamaat')}: <b>${pname(nxt.p)} ${t12(hhmmOf(nxt.d))}</b> • <span data-cd="${+nxt.d}">--</span></div>`:`<div class="muted sm mt">${T('Aaj ki saari jamaaten ho chuki','All of today\'s jamaats are done')}</div>`}</div>`}
/* ---------- MAKRUH TIMES ---------- */
const MKN={rise:['Tulu-e-aftab (Sunrise)','Sunrise','طلوعِ آفتاب','सूर्योदय'],zawal:['Zawal (dopahar)','Zawal (noon)','زوال (دوپہر)','ज़वाल (दोपहर)'],set:['Ghuroob (Sunset)','Sunset','غروبِ آفتاب','सूर्यास्त']};
const mkName=k=>T(MKN[k][0],MKN[k][1],MKN[k][2],MKN[k][3]);
function mkWindows(d=new Date(),tm=TM){if(!tm||!S.mk||!S.mk.on)return[];const at=h=>atTime(h,d),sr=at(tm.t.Sunrise),dh=at(tm.t.Dhuhr),mg=at(tm.t.Maghrib),w=[];
  if(sr)w.push({k:'rise',s:sr,e:new Date(+sr+(+S.mk.rise||15)*60000)});
  if(dh&&d.getDay()!==5)w.push({k:'zawal',s:new Date(+dh-(+S.mk.zawal||10)*60000),e:dh});
  if(mg)w.push({k:'set',s:new Date(+mg-(+S.mk.set||20)*60000),e:mg});return w}
function mkEvents(base,tm){const out=[];mkWindows(base,tm).forEach(w=>{const a=t12(hhmmOf(w.s)),b=t12(hhmmOf(w.e));
  out.push({k:'mk_'+w.k,at:w.s,voice:'makruh',title:T(`⛔ Makruh waqt shuru — ${mkName(w.k)}`,`⛔ Makruh time begins — ${mkName(w.k)}`,`⛔ مکروہ وقت شروع — ${mkName(w.k)}`,`⛔ मकरूह वक़्त शुरू — ${mkName(w.k)}`),body:T(`${a} se ${b} tak nafl namaz aur sajda-e-tilawat na padhein.`,`Do not offer nafl prayer or sajdah of recitation from ${a} to ${b}.`,`${a} سے ${b} تک نفل نماز اور سجدۂ تلاوت نہ پڑھیں۔`,`${a} से ${b} तक नफ़्ल नमाज़ और सज्दा-ए-तिलावत न पढ़ें।`)});
  out.push({k:'mke_'+w.k,at:w.e,silent:true,voice:'silent',title:T('✅ Makruh waqt khatam','✅ Makruh time ended','✅ مکروہ وقت ختم','✅ मकरूह वक़्त ख़त्म'),body:T('Ab nafl namaz padh sakte hain.','You may pray nafl now.')})});return out}
function mkBanner(){const ws=mkWindows(),now=new Date();const cur=ws.find(w=>w.s<=now&&now<w.e);
  if(cur)return`<div class="card mkb on"><div class="row"><span style="font-size:30px">⛔</span><div class="grow"><b>${T('Abhi makruh waqt hai','Makruh time right now','ابھی مکروہ وقت ہے','अभी मकरूह वक़्त है')} — ${mkName(cur.k)}</b><div class="muted sm">${T('Nafl namaz aur sajda-e-tilawat na padhein. Khatam hone mein:','Avoid nafl prayer and sajdah of recitation. Ends in:')} <b data-cd="${+cur.e}">--</b> (${t12(hhmmOf(cur.e))})</div></div></div></div>`;
  const nx=ws.find(w=>w.s>now&&w.s-now<90*60000);
  return nx?`<div class="card mkb"><div class="row"><span style="font-size:24px">⏳</span><div class="grow"><b>${T('Agla makruh waqt','Next makruh time','اگلا مکروہ وقت','अगला मकरूह वक़्त')}: ${mkName(nx.k)}</b><div class="muted sm">${t12(hhmmOf(nx.s))} – ${t12(hhmmOf(nx.e))} • <span data-cd="${+nx.s}">--</span></div></div></div></div>`:''}
/* ---------- JUMMA (separate from Zuhr) ---------- */
function juTimes(d=new Date(),azf,jmf){const M=S.masjid||{};azf=azf||(p=>azanTime(p,d));jmf=jmf||(p=>jamTime(p,d));
  const jz=hm(M.jz)?atTime(M.jz,d):null,ju=hm(M.ju)?atTime(M.ju,d):null;
  return{az:jz||azf('Dhuhr'),jm:ju||jmf('Dhuhr'),set:!!(jz||ju)}}
function juRow(){if(!TM)return'';const j=juTimes(),fri=new Date().getDay()===5;
  return`<div class="ptr ju${fri?' next':''}"><b>🕌 ${T('Jumma','Jumma','جمعہ','जुमा')}</b><span>${t12(TM.t.Dhuhr)}</span><span>${j.az?t12(hhmmOf(j.az)):'—'}</span><span>${j.jm?t12(hhmmOf(j.jm)):'—'}</span></div>`}
function jumaEvents(base,az,jm){const out=[];if(base.getDay()!==5)return out;const j=juTimes(base,az,jm);if(!j.az&&!j.jm)return out;
  const nm=S.masjid&&S.masjid.name?' · '+S.masjid.name:'',jt=j.jm?t12(hhmmOf(j.jm)):'';
  if(false&&j.az)out.push({k:'jz',at:j.az,voice:'juma',tab:'deen',sub:'namaz',title:T('Jumma ki azan 🕌','Jumuah adhan 🕌','جمعہ کی اذان 🕌','जुमा की अज़ान 🕌'),body:T(`Jamaat ${jt} par.`,`Jamaat at ${jt}.`,`جماعت ${jt} پر۔`,`जमात ${jt} पर।`)+nm});
  if(j.jm){const p=new Date(j.jm);p.setMinutes(p.getMinutes()-15);out.push({k:'jp',at:p,voice:'juma',tab:'deen',sub:'namaz',title:T('Jumma ki jamaat 15 min mein','Jumuah in 15 minutes','جمعہ کی جماعت 15 منٹ میں','जुमा की जमात 15 मिनट में'),body:T('Ghusl, saaf libaas, khutba ke liye jaldi masjid.','Ghusl, clean clothes, be early for the khutbah.')+nm})}
  return out}
/* ---------- BOOKMARKS & RESUME ---------- */
function resumeCard(){const rows=[];const q=QS.pos;
  if(q)rows.push(`<div class="sr" data-a="resq"><div class="no"><b>📖</b></div><div class="nm"><b>${T('Quran','Quran')}</b><div class="muted sm">${snm(q.s-1)} • ${T('Ayat','Ayah')} ${q.a}</div></div><span class="chip gold">▶</span></div>`);
  const h=store.get('hd_last',null);if(h){const bk=HB.find(x=>x[0]===h.b);rows.push(`<div class="sr" data-a="resh"><div class="no"><b>📜</b></div><div class="nm"><b>${T('Hadees','Hadith')}</b><div class="muted sm">${bk?bkName(bk):h.b} • ${T('Baab','Section')} ${h.sec} • ${T('Safha','Page')} ${(h.pg||0)+1}</div></div><span class="chip gold">▶</span></div>`)}
  const hv=store.get('hs_vol',null);if(hv){const pg=(store.get('hs_page',[0,0,0,0])[hv]||0);rows.push(`<div class="sr" data-a="resy"><div class="no"><b>🌙</b></div><div class="nm"><b>${T('Hayat-us-Sahaba','Hayat-us-Sahaba')}</b><div class="muted sm">${T('Jild','Vol')} ${hv} • ${T('Safha','Page')} ${pg+1}</div></div><span class="chip gold">▶</span></div>`)}
  return rows.length?`<div class="card"><div class="eyebrow">${T('JAHAN CHHODA THA WAHIN SE JARI RAKHEIN','CONTINUE WHERE YOU LEFT OFF')}</div><div class="card flat mt">${rows.join('')}</div></div>`:''}
let _posT=null,_posRaf=0;
window.addEventListener('scroll',()=>{if(typeof QS==='undefined'||QS.view!=='reader'||curTab!=='deen'||_posRaf)return;_posRaf=requestAnimationFrame(()=>{_posRaf=0;const els=document.querySelectorAll('.q-blk[data-ay],.ay[data-ay]');for(const e of els){const r=e.getBoundingClientRect();if(r.bottom>130){const[s,a]=e.dataset.ay.split(':').map(Number);if(!QS.pos||QS.pos.s!==s||QS.pos.a!==a){QS.pos={s,a};clearTimeout(_posT);_posT=setTimeout(saveQS,700)}break}}})},{passive:true});
function hsBmList(){return store.get('hs_bm',[])}
function hsMarks(el,bar){const L=hsBmList();el.innerHTML=bar+`<div class="card flat">${L.length?L.map(b=>`<div class="sr" data-a="hsgo" data-v="${b.v}" data-p="${b.p}"><div class="no"><b>${b.p+1}</b></div><div class="nm"><b>${T('Jild','Vol')} ${b.v} • ${T('Safha','Page')} ${b.p+1}</b><div class="muted sm">${esc(b.t||'')}</div></div><span>🔖</span></div>`).join(''):`<p class="muted c">${T('Koi bookmark nahi. Page par 🔖 dabayein.','No bookmarks. Tap 🔖 on a page.')}</p>`}</div>`}
/* ---------- action handlers ---------- */
AX.dmt=el=>{DM.t=el.dataset.v;rerender()};
AX.dmplay=(el)=>dmPlay(el.dataset.p,el);
AX.dmopen=el=>{DM.iq='';DM.o=+el.dataset.id;rerender();window.scrollTo(0,0)};
AX.dmback=()=>{DM.iq='';DM.o=null;rerender()};
AX.dmcopy=async el=>{const D=DM.data;if(!D)return;const c=D.find(x=>x.id===+el.dataset.c),x=c&&c.array.find(y=>y.id===+el.dataset.i);if(x){try{await navigator.clipboard.writeText(x.text);toast(T('Copy ho gaya ✅','Copied ✅'))}catch(e){}}};
AX.dmcopy2=async el=>{const c=CUR.find(x=>curKey(x)===el.dataset.k);if(c){try{await navigator.clipboard.writeText(c.ar+'\n'+trOf(c));toast(T('Copy ho gaya ✅','Copied ✅'))}catch(e){}}};
AX.dmmem=el=>{const k=el.dataset.k;DMEM[k]=DMEM[k]?0:1;store.set('dua_mem',DMEM);sfx(DMEM[k]?'success':'tick');rerender()};
AX.dmtest=el=>{VO.stop();VO.say(el.dataset.v)};
AX.nattest=()=>{if(!window.AndroidPA){toast(T('Ye test sirf APK mein hai','APK only'));return}try{const items=natItems();items.push({at:Date.now()+10000,title:T('Test notification ✅','Test notification ✅'),body:T('Agar ye awaaz ke saath aaya to alarm theek hain.','If you heard this, alarms are working.'),voice:'dua_wake',tab:'home',sub:''});window.AndroidPA.sync(JSON.stringify({lang:VL(),voice:!!S.voice,items:items.sort((a,b)=>a.at-b.at).slice(0,380)}));toast(T('10 second mein notification aayegi — phone lock kar dein','Notification in 10 s — lock the phone'),5000)}catch(e){toast('err')}};
AX.qbstart=()=>qiblaToggle();
AX.mqfind=()=>mqFind();
AX.favtog=el=>{const id=el.dataset.id,m=MQ.list&&MQ.list.L.find(x=>x.id===id);if(!m)return;const i=S.favs.findIndex(f=>f.id===id);if(i>=0){S.favs.splice(i,1);if(S.favAct>=S.favs.length)S.favAct=0}else{S.favs.push({id,name:m.n,lat:m.lat,lng:m.lng,az:{},jm:{}});if(S.favs.length===1)favApply(0);else saveS();toast(T('Favourite mein jod di ⭐ — ab ⏱ se jamaat ka waqt likhein','Added ⭐ — now set jamaat times with ⏱'),3600)}saveS();rerender()};
AX.favuse=el=>{favApply(+el.dataset.i);toast(T('Home par set ho gayi ✅','Set on Home ✅'));rerender()};
AX.favedit=el=>favForm(+el.dataset.i);
AX.favdel=el=>{const i=+el.dataset.i;S.favs.splice(i,1);if(S.favAct>=S.favs.length)S.favAct=0;if(S.favs.length)favApply(S.favAct);else{S.masjid.name='';S.masjid.az={};S.masjid.jm={}}saveS();rerender()};
AX.resq=()=>{if(!QS.pos)return;QS.view='reader';QS.s=QS.pos.s;QS.target=QS.pos.a;saveQS();go('deen','quran')};
AX.resh=()=>{const h=store.get('hd_last',null);if(!h)return;HD.v='book';HD.b=h.b;HD.sec=h.sec;HD.page=h.pg||0;KU.v='hadith';go('deen','kutub')};
AX.resy=()=>{KU.v='hayat';HS.v='read';go('deen','kutub')};
AX.qbmpos=()=>{const p=QS.pos||{s:QS.s,a:1},i=QS.bm.findIndex(x=>x.s===p.s&&x.a===p.a);if(i>=0){QS.bm.splice(i,1);toast(T('Bookmark hata diya','Bookmark removed'))}else{QS.bm.unshift({s:p.s,a:p.a});toast(T(`Bookmark lag gaya 🔖 ${snm(p.s-1)} ${p.a}`,`Bookmarked 🔖 ${snm(p.s-1)} ${p.a}`))}saveQS();rerender()};
AX.hsbm=()=>{const v=HS.vol,p=HS.page[v]||0,L=hsBmList(),i=L.findIndex(b=>b.v===v&&b.p===p);if(i>=0){L.splice(i,1);toast(T('Bookmark hata diya','Bookmark removed'))}else{const t=(HS.data[v]&&HS.data[v].p[p]||[]).find(x=>x.startsWith('# '));L.unshift({v,p,t:t?t.slice(2).trim():''});toast(T('Bookmark lag gaya 🔖','Bookmarked 🔖'))}store.set('hs_bm',L);rerender()};
/* ---------- first-run setup: location + own masjid times + notifications ---------- */
function setupState(){const loc=S.lat!=null,M=S.masjid||{},msj=!!(M.name||Object.keys(M.az||{}).length||Object.keys(M.jm||{}).length);return{loc,msj}}
function setupCard(dlgMode){if(S.setupDone)return'';const st=setupState(),ck=b=>b?'✅':'⬜';
  const step=(ok,t,d,btns)=>`<div class="fs" style="display:block;padding:10px 0;border-bottom:1px solid var(--bd,rgba(255,255,255,.08))"><div><b>${ck(ok)} ${t}</b></div><div class="muted sm" style="margin:2px 0 8px">${d}</div><div class="row wrap">${btns}</div></div>`;
  return`<div class="card hero" id="setupc"><div class="row sp"><h2 style="margin:0">🕌 ${T('Pehli baar setup','First-time setup','پہلی بار سیٹ اپ','पहली बार सेटअप')}</h2>${dlgMode?`<button class="btn s ghost" data-a="closedlg">✕</button>`:''}</div>
  <p class="muted sm">${T('3 chhote kaam — phir namaz ke auqat aur notification aapki apni jagah aur masjid ke hisab se aayenge.','3 quick steps — then prayer times and alerts follow your own place and masjid.','۳ چھوٹے کام — پھر نماز کے اوقات اور نوٹیفکیشن آپ کی جگہ اور مسجد کے حساب سے آئیں گے۔','3 छोटे काम — फिर नमाज़ के औक़ात और नोटिफ़िकेशन आपकी जगह और मस्जिद के हिसाब से आएँगे।')}</p>
  ${step(st.loc,T('1. Location','1. Location','۱۔ لوکیشن','1. लोकेशन'),T('Aapke shehar ke hisab se namaz ke sahi auqat.','Correct prayer times for your place.','آپ کے شہر کے حساب سے نماز کے صحیح اوقات۔','आपके शहर के हिसाब से नमाज़ के सही औक़ात।')+' '+locChip(),`<button class="btn s" data-a="autoloc">📍 ${T('Meri current location (auto)','My current location (auto)','میری موجودہ لوکیشن (آٹو)','मेरी मौजूदा लोकेशन (ऑटो)')}</button><button class="btn s ghost" data-a="setloc">✏️ ${T('Shehar likhein','Type city','شہر لکھیں','शहर लिखें')}</button>`)}
  ${step(st.msj,T('2. Apni masjid ke waqt','2. Your masjid times','۲۔ اپنی مسجد کے اوقات','2. अपनी मस्जिद के वक़्त'),T('Apni masjid ka azan aur jamaat ka waqt bharein — notification usi hisab se aayegi.','Enter your masjid azan and jamaat times — alerts will follow them.','اپنی مسجد کی اذان اور جماعت کا وقت بھریں — نوٹیفکیشن اسی حساب سے آئے گی۔','अपनी मस्जिद की अज़ान और जमात का वक़्त भरें — नोटिफ़िकेशन उसी हिसाब से आएगी।')+(S.masjid.name?' 🕌 '+esc(S.masjid.name):''),`<button class="btn s" data-a="masjid">🕌 ${T('Azan/Jamaat waqt bharein','Enter times','اذان/جماعت کا وقت','अज़ान/जमात का वक़्त')}</button><button class="btn s ghost" data-a="setupnear">🔎 ${T('Qareeb ki masjid dhundhein','Find nearby masjids','قریب کی مسجد','क़रीब की मस्जिद')}</button>`)}
  ${step(false,T('3. Notification / Alarm','3. Notifications / alarms','۳۔ نوٹیفکیشن / الارم','3. नोटिफ़िकेशन / अलार्म'),T('Namaz ka waqt shuru hote hi, azan par, aur jamaat ke baad — chhoti awaaz ke saath.','At prayer start, at azan and after jamaat — with a short voice.','نماز کا وقت شروع ہوتے ہی، اذان پر اور جماعت کے بعد — مختصر آواز کے ساتھ۔','नमाज़ का वक़्त शुरू होते ही, अज़ान पर और जमात के बाद — छोटी आवाज़ के साथ।'),`<button class="btn s" data-a="setupnotif">🔔 ${T('Ijazat dein','Allow','اجازت دیں','इजाज़त दें')}</button>`)}
  <div class="fs"><span>${T('Waqt shuru hote hi notification','Notify when prayer time begins','وقت شروع ہوتے ہی نوٹیفکیشن','वक़्त शुरू होते ही नोटिफ़िकेशन')}</span><input type="checkbox" class="sw" data-a="set" data-p="waqtNotif" data-t="check" ${S.waqtNotif!==false?'checked':''}></div>
  <div class="fs"><span>${T('Masjid ke azan par notification','Notify at masjid azan','مسجد کی اذان پر نوٹیفکیشن','मस्जिद की अज़ान पर नोटिफ़िकेशन')}</span><input type="checkbox" class="sw" data-a="set" data-p="azan" data-t="check" ${S.azan?'checked':''}></div>
  <button class="btn gold mt" style="width:100%" data-a="setupdone">✅ ${T('Setup poora','Setup done','سیٹ اپ مکمل','सेटअप पूरा')}</button></div>`}
AX.setupdone=()=>{S.setupDone=true;saveS();closeDlg();toast(T('Setup poora ✅','Setup done ✅'));rerender()};
AX.setupnotif=async()=>{await askNotifPerm();toast(T('Ijazat maangi — allow kar dein, phir Settings me test dabayein','Permission requested'));try{schedTick();nativeSync()}catch(e){}};
AX.setupnear=()=>{closeDlg();go('deen','namaz');setTimeout(()=>{try{AX.mqfind()}catch(e){}},700)};
function firstRun(){{const z=setupState();if(!S.setupDone&&z.loc&&z.msj){S.setupDone=true;saveS()}}if(S.setupDone||store.get('setup_shown',0))return;const t=setInterval(()=>{if(typeof LCK!=='undefined'&&LCK.locked)return;const sp=document.getElementById('splash');if(sp&&!sp.hidden&&sp.offsetParent!==null&&getComputedStyle(sp).display!=='none')return;clearInterval(t);if($('#dlg').open)return;store.set('setup_shown',1);dlg(setupCard(true))},800);setTimeout(()=>clearInterval(t),20000)}
/* ---------- automatic current location (GPS) ---------- */
const ALC={t:0,busy:false};
async function autoLoc(manual){if(!manual&&S.autoLoc===false)return;if(ALC.busy||!navigator.geolocation)return;if(!manual&&Date.now()-ALC.t<20*60000)return;
  try{if(!manual&&navigator.permissions&&navigator.permissions.query){const q=await navigator.permissions.query({name:'geolocation'});if(q.state!=='granted'&&S.lat!=null)return}}catch(x){}
  ALC.busy=true;
  navigator.geolocation.getCurrentPosition(async p=>{ALC.busy=false;ALC.t=Date.now();const la=p.coords.latitude,lo=p.coords.longitude;const moved=S.lat==null?99999:distKm(S.lat,S.lng,la,lo);
    if(moved>=2){S.lat=la;S.lng=lo;saveS();MQ.list=null;try{store.set('mq_list',null)}catch(x){}try{await loadTimes(true)}catch(x){}try{nativeSync()}catch(x){}toast(T('📍 Aapki current location mil gayi — namaz ke auqat update','📍 Current location updated — prayer times refreshed'));rerender()}
    else if(manual)toast(T('📍 Location wahi hai (badli nahi)','📍 Location unchanged'))},
  err=>{ALC.busy=false;ALC.t=Date.now()-15*60000;if(manual)toast(T('Location ki ijazat/GPS chalu karein','Allow location / turn GPS on'))},{timeout:15000,maximumAge:10*60000,enableHighAccuracy:false})}
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&(typeof LCK==='undefined'||!LCK.locked))setTimeout(()=>autoLoc(),1500)});
AX.autoloc=()=>autoLoc(true);
function homeExtras(){try{return setupCard(false)+favHomeCard()+(typeof kaamHomeCard==='function'?kaamHomeCard():'')+resumeCard()}catch(e){console.error(e);return''}}
AX.sfmark=el=>{const k=el.dataset.k,tk=store.get(sfKey(),{});tk[k]=tk[k]?0:1;store.set(sfKey(),tk);sfx(tk[k]?'success':'tick');rerender()};
/* ---------- wrap existing pages ---------- */
(function(){
  const _rn=renderNamaz;renderNamaz=function(el){_rn(el);el.insertAdjacentHTML('afterbegin',mkBanner());el.insertAdjacentHTML('beforeend',favListCard()+nearCard()+qiblaCard());if(QB.on&&QB.h!=null)qiblaDraw()};
  const _rq=renderQuran;renderQuran=async function(el){await _rq(el);if(QS.view!=='reader'){const r=resumeCard();if(r&&QS.pos)el.insertAdjacentHTML('afterbegin',`<div class="card tap" data-a="resq"><div class="row sp"><div><div class="eyebrow">${T('JAHAN CHHODA THA','CONTINUE')}</div><b>${snm(QS.pos.s-1)} • ${T('Ayat','Ayah')} ${QS.pos.a}</b></div><span class="chip gold">▶ ${T('Jari rakhein','Resume')}</span></div></div>`)}};
})();


